/* ===== ORDER FLOW ===== */
const CO_STEPS=['Choose Package','Your Brand','Materials','Delivery','Summary & Pay'];
const MATS=[['logo','Logo','image','Logo_BhojKitchen.png'],['img','Product images','image','Kacchi_platter_01.jpg'],['vid','Product video','video','Kitchen_broll.mp4'],['script','Script','doc','Script_draft_v1.docx'],['guide','Brand guidelines','file','Brand_guidelines.pdf'],['ref','Reference videos','video','Reference_reel_link.txt']];
function addDays(n){const d=new Date(2026,9,3+n);return d.toISOString().slice(0,10);}
function niceDate(s){const d=new Date(s+'T00:00:00');return isNaN(d)?s:d.toLocaleDateString('en-GB',{day:'2-digit',month:'short'});}
function coInit(cid,p){if(!S.co||S.co.c!==cid){S.co={c:cid,pkg:p!=null&&p!==''?+p:1,step:1,files:{},date:addDays(7),format:'9:16 vertical',plats:new Set(['Facebook','Instagram']),pay:'bkash',
 brief:{biz:'Bhoj Kitchen',web:'bhojkitchen.com.bd',product:'Friday family kacchi platter (serves 4)',aud:'Families and office groups in Dhanmondi, age 22–45',goal:'Drive weekend table bookings',lang:'Bangla',tone:'Warm and family-friendly',notes:'Mention the 15% weekend discount and show a close-up of the platter.'}};}
 else if(p!=null&&p!==''&&S.co.step===1)S.co.pkg=+p;}
PAGES.order=(cid,p)=>{const c=C(cid)||C('c1');coInit(c.id,p);const co=S.co,P=pkgs(c),pk=P[co.pkg];
 return `<div class="phead" style="padding-block:22px"><div class="wrap"><div class="crumbs"><button data-go="explore">Explore</button>${ic('chevr')}<button data-go="creator~${c.id}">${esc(c.name)}</button>${ic('chevr')}<span>Order</span></div><h1 style="font-size:clamp(26px,3vw,34px)">Order a promotional video</h1></div></div>
 <div class="wrap co"><div style="min-width:0"><div class="stepper">${CO_STEPS.map((s,i)=>`<button class="${i+1<co.step?'done':''} ${i+1===co.step?'on':''}" data-act="coGo" data-n="${i+1}"><small>Step ${i+1}</small><span>${s}</span></button>`).join('')}</div>
 <div class="card pad" style="padding:clamp(18px,3vw,28px)" id="co-step">${coStep(c)}</div>
 <div class="row between" style="margin-top:18px">${co.step>1?`<button class="btn btn-ghost" data-act="coGo" data-n="${co.step-1}">${ic('chevl')}Back</button>`:`<button class="btn btn-ghost" data-go="creator~${c.id}">${ic('chevl')}Back to profile</button>`}
 ${co.step<5?`<button class="btn btn-pri" data-act="coGo" data-n="${co.step+1}">Continue${ic('chevr')}</button>`:`<button class="btn btn-pri btn-lg" data-act="pay">${ic('lock')}Pay Securely · ${tk(pk.price)}</button>`}</div></div>
 <aside class="stack" style="position:sticky;top:88px">${coSummary(c)}</aside></div>`;};
function coSummary(c){const co=S.co,pk=pkgs(c)[co.pkg];return `<div class="card pad stack" style="gap:14px"><div class="row">${av(c,48)}<div><b>${esc(c.name)} ${vb()}</b><div class="small muted">${c.cats[0]} · ${c.city}</div></div></div>
 <div style="padding:12px;border-radius:10px;background:var(--bg-2)"><b>${pk.n} package</b><div class="small muted">${pk.desc} · ${pk.days}-day delivery · ${pk.rev} revision${pk.rev>1?'s':''}</div></div>
 <div class="sumrow"><span>Creator fee</span><span class="tnum">${tk(pk.price)}</span></div><div class="sumrow"><span>BitPromo service &amp; protection fee</span><span class="tnum" style="color:var(--good);font-weight:650">Included</span></div>
 <div class="sumrow total"><span>Total</span><span class="tnum">${tk(pk.price)}</span></div>
 <div class="protect">${ic('shield')}<span>Your money is protected. BitPromo holds the payment until you approve the video.</span></div>
 <p class="small muted">BitPromo’s 20% commission (${tk(pk.price*.2)}) comes out of the creator’s earnings, not your bill.</p></div>`;}
function coStep(c){const co=S.co,P=pkgs(c),b=co.brief;const inp=(k,l,ph,full)=>`<div class="${full?'full':''}"><label for="co-${k}">${l}</label><input class="field" id="co-${k}" data-co="${k}" value="${esc(b[k])}" placeholder="${ph}"></div>`;
 const selF=(k,l,opts)=>`<div><label for="co-${k}">${l}</label><select class="field" id="co-${k}" data-co="${k}">${opts.map(o=>`<option ${b[k]===o?'selected':''}>${o}</option>`).join('')}</select></div>`;
 if(co.step===1)return `<h2 style="font-size:22px">Choose your package</h2><p class="muted" style="margin:6px 0 18px">All packages include BitPromo payment protection and a quality check.</p><div class="pkg-pick">${P.map((p,i)=>`<button class="pkg-opt ${i===co.pkg?'on':''}" data-act="coPkg" data-i="${i}"><span class="row between"><b>${p.n}</b>${i===co.pkg?`<span class="vbadge">${ic('check')}</span>`:''}</span><span class="pkg-price" style="font-size:24px">${tk(p.price)}</span><span class="small muted">${p.desc}</span><span class="small">${ic('clock')} ${p.days} days · ${ic('refresh')} ${p.rev} rev.</span><span class="small muted">${FEATS.filter(([k])=>p.f[k]).map(([,l])=>l).join(' · ')}</span></button>`).join('')}</div>`;
 if(co.step===2)return `<h2 style="font-size:22px">Tell us about your brand</h2><p class="muted" style="margin:6px 0 18px">A clear brief is how the creator, and our quality check, know what “done” looks like. <span class="tag">Sample brief filled in for the demo</span></p>
 <div class="form">${inp('biz','Business name','Your business name')}${inp('web','Website or Facebook page','www…')}${inp('product','Product or service to promote','What should the video feature?',1)}${inp('aud','Target audience','Who should this reach?',1)}${inp('goal','Campaign objective','e.g. more bookings, app installs')}${selF('lang','Preferred language',['Bangla','English','Bangla + English','Hindi'])}${selF('tone','Tone',['Warm and family-friendly','Energetic and fun','Premium and elegant','Informative and trustworthy','Comedic'])}
 <div class="full"><label for="co-notes">Anything the creator must say or show?</label><textarea class="field" id="co-notes" data-co="notes">${esc(b.notes)}</textarea></div></div>`;
 if(co.step===3)return `<h2 style="font-size:22px">Upload your materials</h2><p class="muted" style="margin:6px 0 18px">Optional. You can also share files later in the order chat. <button class="btn-link" data-act="coSample">Add sample files</button></p>
 <div class="grid g2" style="gap:14px">${MATS.map(([k,l,i])=>`<div class="drop"><div class="drop-head"><span class="fi">${ic(i)}</span><div class="grow"><b style="font-size:14.5px">${l}</b><div class="small muted">${(co.files[k]||[]).length?`${co.files[k].length} file${co.files[k].length>1?'s':''} added`:'No files yet'}</div></div><label class="btn btn-ghost btn-sm" for="up-${k}" style="cursor:pointer">${ic('upload')}Upload</label><input type="file" id="up-${k}" data-up="${k}" multiple hidden></div>${(co.files[k]||[]).length?`<div class="row" style="gap:6px">${co.files[k].map(f=>`<span class="filechip">${ic('check')}${esc(f)}</span>`).join('')}</div>`:''}</div>`).join('')}</div>`;
 if(co.step===4)return `<h2 style="font-size:22px">Delivery requirements</h2><p class="muted" style="margin:6px 0 18px">${pkgs(c)[co.pkg].n} package delivers in ${pkgs(c)[co.pkg].days} days. Pick a date on or after that.</p>
 <div class="form"><div><label for="co-date">Expected delivery date</label><input type="date" class="field" id="co-date" data-cod="date" value="${co.date}" min="${addDays(pkgs(c)[co.pkg].days)}"></div><div></div>
 <div class="full"><label>Video format</label><div class="chips">${['9:16 vertical','16:9 landscape','1:1 square'].map(f=>`<button class="chipt ${co.format===f?'on':''}" data-act="coFmt" data-v="${f}">${f}</button>`).join('')}</div></div>
 <div class="full"><label>Where will you post it?</label><div class="chips">${['Facebook','Instagram','TikTok','YouTube','Website','Other'].map(f=>`<button class="chipt ${co.plats.has(f)?'on':''}" data-act="coPlat" data-v="${f}">${co.plats.has(f)?ic('check'):''}${f}</button>`).join('')}</div></div></div>`;
 const pk=P[co.pkg],nf=Object.values(co.files).flat().length;
 return `<h2 style="font-size:22px">Order summary</h2><p class="muted" style="margin:6px 0 18px">Check the details, choose how to pay, and BitPromo will hold your payment until you approve the video.</p>
 <div class="grid g2" style="gap:14px">${[['Package',`${pk.n} · ${pk.desc}`,1],['Business',b.biz||'—',2],['Promoting',b.product||'—',2],['Audience',b.aud||'—',2],['Language & tone',`${b.lang} · ${b.tone}`,2],['Delivery',`${niceDate(co.date)} · ${co.format}`,4],['Platforms',[...co.plats].join(', ')||'—',4],['Materials',nf?`${nf} file${nf>1?'s':''} attached`:'None yet',3]].map(([k,v,s])=>`<div style="padding:12px 14px;border:1px solid var(--line);border-radius:10px;min-width:0"><div class="row between"><span class="small muted" style="font-weight:650">${k}</span><button class="btn-link small" data-act="coGo" data-n="${s}">Edit</button></div><div style="font-weight:600;overflow-wrap:anywhere">${esc(v)}</div></div>`).join('')}</div>
 <h3 style="margin:26px 0 12px">Payment method</h3><div class="paym">${[['bkash','bKash','#E2136E'],['nagad','Nagad','#EC1C24'],['card','Card','#1F2A44'],['bank','Bank','#0F9F6E']].map(([k,l,col])=>`<button class="${co.pay===k?'on':''}" data-act="coPay" data-v="${k}"><span class="lg" style="background:${col}">${l.slice(0,2).toUpperCase()}</span>${l}</button>`).join('')}</div>
 <div class="demo-note" style="margin-top:16px">${ic('alert')}Prototype: no real payment is taken. bKash, Nagad, card and bank options are shown for design only.</div>`;}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset&&t.dataset.co&&S.co)S.co.brief[t.dataset.co]=t.value;if(t.dataset&&t.dataset.cod&&S.co)S.co[t.dataset.cod]=t.value;});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset&&t.dataset.co&&S.co)S.co.brief[t.dataset.co]=t.value;if(t.dataset&&t.dataset.up&&S.co){const k=t.dataset.up;S.co.files[k]=[...(S.co.files[k]||[]),...[...t.files].map(f=>f.name)];coRefresh();toast(`${t.files.length} file${t.files.length>1?'s':''} added`);}
 if(t.dataset&&t.dataset.vup){S.ver.files[t.dataset.vup]=t.files[0]?.name||'document.jpg';render();}});
function coRefresh(){render();const el=$('.stepper');if(el)el.scrollIntoView({block:'nearest'});}
ACT.coGo=el=>{const n=+el.dataset.n;if(S.co.step===2&&n>2&&!S.co.brief.biz.trim()){toast('Add your business name to continue');return;}S.co.step=n;render();window.scrollTo({top:0});};
ACT.coPkg=el=>{S.co.pkg=+el.dataset.i;render();};
ACT.coSample=()=>{MATS.forEach(([k,,,f])=>{if(!(S.co.files[k]||[]).length)S.co.files[k]=[f];});render();toast('Sample files attached');};
ACT.coFmt=el=>{S.co.format=el.dataset.v;render();};
ACT.coPlat=el=>{const v=el.dataset.v;S.co.plats.has(v)?S.co.plats.delete(v):S.co.plats.add(v);render();};
ACT.coPay=el=>{S.co.pay=el.dataset.v;render();};
ACT.pay=()=>{const co=S.co,c=C(co.c),pk=pkgs(c)[co.pkg];const method={bkash:'bKash',nagad:'Nagad',card:'Card',bank:'Bank transfer'}[co.pay];
 modal(`<div class="modal-body" style="text-align:center;padding:40px 24px"><div class="spinner"></div><h3>Securing your payment</h3><p class="muted">Sending ${tk(pk.price)} via ${method} to BitPromo payment protection…</p></div>`);
 setTimeout(()=>{const id='BP-'+(S.nextId++);ORDERS.unshift({id,b:ME_BIZ,c:c.id,pkg:co.pkg,title:`${pk.desc}: ${co.brief.product||'your product'}`,st:1,created:'Oct 03',due:niceDate(co.date),revUsed:0,brief:{...co.brief,plats:[...co.plats].join(', '),format:co.format},files:Object.values(co.files).flat(),paid:method});
  S.role='biz';S.co=null;
  modal(`<div class="modal-body" style="text-align:center;padding:36px 26px"><div class="success-ic">${ic('check')}</div><h2 style="font-size:26px">Order placed</h2><p class="muted">Order <b class="tnum" style="color:var(--ink)">${id}</b> is with ${esc(c.name)}. Your ${tk(pk.price)} is held by BitPromo until you approve the video.</p>
  <div class="stack" style="gap:10px;margin-top:8px"><button class="btn btn-pri btn-block" data-go="track~${id}">Track your order</button><button class="btn btn-ghost btn-block" data-go="dash~biz~home">Go to dashboard</button></div></div>`);},1500);};

/* ===== ORDER TRACKING ===== */
const defBrief=o=>({biz:B(o.b).name,product:o.title,aud:'Young adults and families in '+B(o.b).city+', age 20–40',goal:'Increase awareness and drive orders',lang:'Bangla',tone:'Warm and friendly',plats:'Facebook, Instagram',format:'9:16 vertical',notes:'Show the logo in the first 3 seconds and end with the offer.'});
PAGES.track=id=>{const o=O(id)||ORDERS[0],c=C(o.c),b=B(o.b),P=pkgs(c)[o.pkg],role=S.role||'biz',br=o.brief||defBrief(o),A=amt(o);const back=role==='creator'?'dash~creator~orders':role==='admin'?'dash~admin~orders':'dash~biz~orders';
 const files=o.files&&o.files.length?o.files:['Logo_'+b.name.replace(/\W/g,'')+'.png','Product_photo_01.jpg','Brand_guidelines.pdf'];
 return `<div class="phead"><div class="wrap"><div class="crumbs"><button data-go="${back.replace(/~[a-z]+$/,'~home')}">Dashboard</button>${ic('chevr')}<button data-go="${back}">Orders</button>${ic('chevr')}<span>${o.id}</span></div>
 <div class="row between"><div><h1 style="font-size:clamp(24px,3vw,34px)">${esc(o.title)}</h1><div class="row small muted" style="margin-top:8px;gap:14px">${stagePill(o.st)}<span class="tnum">Order ${o.id}</span><span>Placed ${o.created}</span><span>Due ${o.due}</span></div></div>
 <div class="row"><button class="btn btn-ghost btn-sm" data-act="contact" data-id="${c.id}">${ic('message')}Messages</button><button class="btn btn-ghost btn-sm" data-act="dispute" data-id="${o.id}">${ic('flag')}Report a problem</button></div></div>
 <div class="hstl" style="margin-top:24px">${STAGES.map((s,i)=>`<div class="${i<o.st||o.st===7?'done':''} ${i===o.st&&o.st<7?'cur':''}">${s}</div>`).join('')}</div></div></div>
 <div class="wrap co"><div class="stack" style="gap:20px;min-width:0">
 <section class="card pad stack" style="gap:16px"><div class="row between"><h3>Delivery</h3>${o.st>=4?`<span class="tag">${P.dur} sec · ${br.format}</span>`:''}</div>
 <div class="dgrid">${o.st>=4?vt(c,{r:'v',title:o.title,brand:b.name,dur:P.dur,sub:o.st>=7?'Final video':'Draft for review'}):`<div class="vt v" style="--a:var(--bg-2);--b:var(--line);display:grid;place-items:center;cursor:default"><div style="position:relative;z-index:3;color:var(--muted);text-align:center;padding:16px;font-size:13px">${ic('video')}<br>The video appears here once ${first(c)} submits it</div></div>`}
 <div class="stack" style="gap:14px">${trackAction(o,role,c,b,P,A)}</div></div></section>
 ${o.st>=5?`<section class="card pad"><h3 style="margin-bottom:12px">BitPromo quality check</h3><ul class="checks">${[`Duration matches package (${P.dur} sec)`,`${b.name} name and logo visible`,'Offer and price text match the brief','Clear audio, no background noise',`Format is ${br.format}`].map(x=>`<li>${o.st===5?`<span class="muted">${ic('clock')}</span>`:ic('check')}${x}</li>`).join('')}</ul>${o.st===5?'<p class="small muted" style="margin-top:10px">Our team is reviewing the draft against your brief.</p>':'<p class="small muted" style="margin-top:10px">Passed by BitPromo QA · Oct 03</p>'}</section>`:''}
 <section class="card pad"><h3 style="margin-bottom:14px">Campaign brief</h3><div class="grid g2" style="gap:12px 24px">${[['Business',br.biz],['Promoting',br.product],['Audience',br.aud],['Objective',br.goal],['Language',br.lang],['Tone',br.tone],['Platforms',br.plats],['Must include',br.notes]].map(([k,v])=>`<div style="min-width:0"><div class="small muted" style="font-weight:650">${k}</div><div style="overflow-wrap:anywhere">${esc(v)}</div></div>`).join('')}</div>
 <h4 style="margin:20px 0 10px">Files</h4><div class="row" style="gap:8px">${files.map(f=>`<span class="filechip">${ic('file')}${esc(f)}</span>`).join('')}</div></section></div>
 <aside class="stack" style="gap:20px">
 <div class="card pad stack" style="gap:12px"><div class="row">${av(c,44)}<div class="grow"><div class="small muted">Creator</div><b>${esc(c.name)} ${vb()}</b></div></div><div class="row">${bizAv(b,44)}<div class="grow"><div class="small muted">Business</div><b>${esc(b.name)}</b></div></div>
 <div class="sumrow" style="border-top:1px solid var(--line);padding-top:12px"><span class="muted">Package</span><span>${P.n} · ${P.dur} sec</span></div><div class="sumrow"><span class="muted">Order value</span><b class="tnum">${tk(A)}</b></div><div class="sumrow"><span class="muted">Revisions</span><span>${o.revUsed} of ${P.rev} used</span></div><div class="sumrow"><span class="muted">Deadline</span><span>${o.due}</span></div>
 <div class="protect" style="${o.st===7?'':''}">${ic(o.st===7?'check':'lock')}<span>${o.st===7?`Payment released: ${esc(first(c))} received ${tk(A*.8)}, BitPromo commission ${tk(A*.2)}.`:`${tk(A)} held by BitPromo payment protection.`}</span></div></div>
 <div class="card pad"><h3 style="margin-bottom:16px">Order status</h3><ol class="tl">${STAGES.map((s,i)=>{const cls=i<o.st||o.st===7?'done':i===o.st?'cur':'todo';return `<li class="${cls}"><span class="dot">${cls==='done'?ic('check'):i+1}</span><div><b>${s}</b><small>${STAGE_NOTE[i]}</small></div></li>`;}).join('')}</ol></div>
 ${o.st<7?`<div class="demo-note" style="flex-direction:column;align-items:stretch;gap:10px"><span class="row" style="gap:8px">${ic('sliders')}<b style="color:var(--ink)">Prototype control</b></span><span>Move this order forward to show each stage of the flow.</span><button class="btn btn-ghost btn-sm" data-act="advance" data-id="${o.id}">Move to “${STAGES[o.st+1]}”</button></div>`:''}</aside></div>`;};
function trackAction(o,role,c,b,P,A){
 if(o.st===7)return `<div class="row" style="gap:10px"><span class="success-ic" style="width:44px;height:44px;margin:0">${ic('check')}</span><div><h3>Order completed</h3><p class="muted small">Approved and paid out. The final file is ready to download.</p></div></div><div class="row"><button class="btn btn-pri btn-sm" data-act="toastMsg" data-m="Download starts in the live product">Download video</button><button class="btn btn-ghost btn-sm" data-go="order~${c.id}~${o.pkg}">Order again</button></div>
 ${role==='biz'?(o.reviewed?`<div class="protect">${ic('star')}<span>Thanks, your review is published on ${first(c)}'s profile.</span></div>`:`<div style="border-top:1px solid var(--line);padding-top:14px" class="stack"><b>Rate ${first(c)}</b><div class="row" id="rate" style="gap:4px">${[1,2,3,4,5].map(n=>`<button class="iconbtn" data-act="rate" data-n="${n}" aria-label="${n} stars" style="color:${n<=(S.rate||5)?'var(--gold)':'var(--muted)'}">${ic('star','i-fill')}</button>`).join('')}</div><textarea class="field" id="rev-text" placeholder="How was working with ${first(c)}?">Great communication and delivered the video exactly according to the brief.</textarea><button class="btn btn-dark btn-sm" style="align-self:flex-start" data-act="review" data-id="${o.id}">Publish review</button></div>`):''}`;
 if(o.st===6){if(role==='biz')return `<div><h3>Your video is ready to review</h3><p class="muted small" style="margin-top:4px">It passed BitPromo’s quality check. Approve it to release ${tk(A*.8)} to ${first(c)}, or ask for changes.</p></div><div class="row"><button class="btn btn-good" data-act="approve" data-id="${o.id}">${ic('check')}Approve &amp; release payment</button><button class="btn btn-ghost" data-act="revise" data-id="${o.id}" ${o.revUsed>=P.rev?'disabled':''}>${ic('refresh')}Request revision (${P.rev-o.revUsed} left)</button></div><p class="small muted">If you don’t respond within 3 days, the order is approved automatically.</p>`;
  return `<h3>Waiting for ${esc(b.name)} to review</h3><p class="muted small">The draft passed quality check. Payment is released when the buyer approves.</p>`;}
 if(o.st===5)return role==='admin'?`<h3>Quality check</h3><p class="muted small">Compare the draft with the brief, then pass or return it.</p><div class="row"><button class="btn btn-good" data-act="advance" data-id="${o.id}">Pass quality check</button><button class="btn btn-ghost" data-act="toastMsg" data-m="Returned to creator with notes">Return to creator</button></div>`:`<h3>BitPromo is checking the video</h3><p class="muted small">We compare the draft with your brief: duration, branding, offer text, audio and format.</p>`;
 if(o.st===4)return `<h3>Draft video submitted</h3><p class="muted small">${first(c)} uploaded the draft. It goes to BitPromo’s quality check next.</p>`;
 if(o.st>=2)return role==='creator'?`<h3>You’re in production</h3><p class="muted small">Upload the draft when it’s ready. Deadline: ${o.due}.</p><button class="btn btn-pri" style="align-self:flex-start" data-act="upVideo" data-id="${o.id}">${ic('upload')}Upload video</button>`:`<h3>${first(c)} is ${o.st===2?'preparing to film':'filming your video'}</h3><p class="muted small">Delivery expected by ${o.due}. You can message ${first(c)} any time.</p>`;
 return role==='creator'?`<h3>New order request</h3><p class="muted small">${esc(b.name)} sent a brief for ${P.n} (${tk(A)}). You’ll receive ${tk(A*.8)} after approval.</p><div class="row"><button class="btn btn-good" data-act="accept" data-id="${o.id}">Accept order</button><button class="btn btn-ghost" data-act="toastMsg" data-m="Declined. The buyer is refunded in full.">Decline</button></div>`:`<h3>Waiting for ${first(c)} to accept</h3><p class="muted small">Creators usually reply within ${c.resp}. Your payment is safe with BitPromo.</p>`;}
ACT.advance=el=>{const o=O(el.dataset.id);if(o.st<7)o.st++;toast(`Order moved to “${STAGES[o.st]}”`);render();};
ACT.accept=el=>{const o=O(el.dataset.id);o.st=2;toast('Order accepted. Time to plan the shoot!');render();};
ACT.upVideo=el=>{const o=O(el.dataset.id);o.st=4;toast('Video uploaded and sent to quality check');render();};
