function tWho(t){if(t.w[0]==='c'){const c=C(t.w[1]);return{n:c.name,a:av(c,40),s:c.cats[0]};}if(t.w[0]==='b'){const b=B(t.w[1]);return{n:b.name,a:bizAv(b,40),s:b.type};}return{n:'BitPromo Support',a:`<span class="logo-mark" style="width:40px;height:40px;border-radius:12px;flex:none">${ic('play','i-fill')}</span>`,s:'Usually replies in minutes'};}
function bubble(m,t){const[who,txt,time,kind]=m;if(who==='sys')return `<div class="bub sys">${ic('shield')} ${esc(txt)}</div>`;
 let inner=esc(txt);if(kind==='file')inner=`<span class="filechip" style="background:rgba(127,127,127,.14)">${ic('file')}${esc(txt)}</span>`;
 if(kind==='video'){const c=C(t.w[0]==='c'?t.w[1]:'c1');inner=`${esc(txt)}${vt(c,{r:'v',title:'Draft v1',brand:t.w[0]==='c'?'Bhoj Kitchen':B(t.w[1]).name,dur:30})}`;}
 return `<div class="bub ${who==='me'?'me':''}">${inner}<small>${time}</small></div>`;}
function msgUI(role){const list=THREADS.filter(t=>t.role===role);if(!list.length)return `<div class="empty">No conversations yet.</div>`;if(!S.thread||!list.find(t=>t.id===S.thread))S.thread=list[0].id;const t=list.find(x=>x.id===S.thread),w=tWho(t);t.unread=0;
 return `<div class="card msgs"><div class="convs">${list.map(x=>{const ww=tWho(x),last=x.msgs[x.msgs.length-1];return `<button class="conv ${x.id===t.id?'on':''}" data-act="thread" data-id="${x.id}">${ww.a}<div class="grow"><b><span>${esc(ww.n)}</span>${x.unread?`<span class="pill p-acc">${x.unread}</span>`:''}</b><span>${x.order?x.order+' · ':''}${esc(last[1])}</span></div></button>`;}).join('')}</div>
 <div class="thread"><div class="thread-head">${w.a}<div class="grow"><b>${esc(w.n)}</b><div class="small muted">${esc(w.s)}</div></div>${t.order?`<button class="btn btn-ghost btn-sm" data-go="track~${t.order}">${ic('package')}${t.order}</button>`:''}</div>
 <div class="warnbar">${ic('shield')}Keep payments and order communication within BitPromo for transaction protection.</div>
 <div class="thread-body" id="tb">${t.msgs.map(m=>bubble(m,t)).join('')}</div>
 <form class="composer" data-form="msg"><button type="button" class="iconbtn" data-act="attach" aria-label="Attach a file">${ic('clip')}</button><input class="field" name="m" id="msg-input" placeholder="Write a message…" autocomplete="off"><button class="btn btn-pri" type="submit">${ic('send')}</button></form></div></div>`;}
function tbScroll(){const tb=$('#tb');if(tb)tb.scrollTop=tb.scrollHeight;}
function nowT(){return 'Today, '+new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});}
FORM.msg=f=>{const v=f.m.value.trim();if(!v)return;const t=THREADS.find(x=>x.id===S.thread);t.msgs.push(['me',v,nowT()]);render();$('#msg-input').focus();
 setTimeout(()=>{const rep=t.w[0]==='s'?'Thanks for reaching out! A BitPromo specialist will follow up shortly.':['Got it, I’ll take care of that!','Sounds good. I’ll update you soon.','Thanks! Noted for the next draft.'][t.msgs.length%3];t.msgs.push(['them',rep,nowT()]);if($('#tb')&&S.thread===t.id){$('#tb').insertAdjacentHTML('beforeend',bubble(t.msgs[t.msgs.length-1],t));tbScroll();}},1300);};
