DASH.admin.campaigns=()=>dhead('Campaigns','Open campaign briefs from businesses.')+`<div class="card">${table([['Campaign'],['Business'],['Budget','num'],['Applications','num'],['Status']],CAMPAIGNS.map(k=>({go:'campaigns',cells:[`<b>${esc(k.title)}</b>`,esc(B(k.b).name),tk(k.budget),k.apps,'<span class="pill p-good">Live</span>']})))}</div>`;
DASH.admin.reports=()=>dhead('Reports','Marketplace performance, Apr–Sep 2026.')+`<div class="grid g2"><div class="card pad"><h3>GMV (৳ lakh)</h3>${barChart(GMV,{fmt:v=>v+'L',label:'GMV'})}</div><div class="card pad"><h3>BitPromo revenue (৳ lakh)</h3>${barChart(GMV.map(([m,v])=>[m,+(v*.2).toFixed(2)]),{fmt:v=>(+v.toFixed(2))+'L',label:'Revenue'})}</div>
 <div class="card pad"><h3 style="margin-bottom:14px">Orders by category</h3><div class="bars">${[['Food Creators',24],['Influencers',21],['Actors',14],['Comedians',12],['Presenters',10],['Voice Artists',9],['Others',10]].map(([k,v])=>`<div class="bar-row"><span>${k}</span><div class="bar-track"><i style="width:${v*4}%"></i></div><span class="tnum small muted">${v}%</span></div>`).join('')}</div></div>
 <div class="card pad"><h3 style="margin-bottom:14px">Orders by city</h3><div class="bars">${[['Dhaka',58],['Chattogram',16],['Sylhet',9],['Rajshahi',7],['Khulna',6],['Cumilla',4]].map(([k,v])=>`<div class="bar-row"><span>${k}</span><div class="bar-track"><i style="width:${v*1.6}%;background:var(--good)"></i></div><span class="tnum small muted">${v}%</span></div>`).join('')}</div></div></div>`;
DASH.admin.settings=()=>dhead('Platform settings','Marketplace rules applied to every order.')+`<form class="card pad form" data-form="saved"><div><label for="as-1">Commission rate (%)</label><input class="field" id="as-1" value="20" type="number"></div><div><label for="as-2">Auto-approve after buyer silence (days)</label><input class="field" id="as-2" value="3" type="number"></div><div><label for="as-3">Default revisions (Basic)</label><input class="field" id="as-3" value="1" type="number"></div><div><label for="as-4">Creator payout hold after approval (days)</label><input class="field" id="as-4" value="2" type="number"></div><div class="full"><label for="as-5">Community guidelines URL</label><input class="field" id="as-5" value="bitpromo.com.bd/guidelines"></div><div class="full"><button class="btn btn-pri" type="submit">Save settings</button></div></form>`;

