PAGES.campaigns=()=>{const cats=['All',...new Set(CAMPAIGNS.map(k=>k.cat))];const list=CAMPAIGNS.filter(k=>S.campCat==='All'||k.cat===S.campCat);
 return `<div class="phead"><div class="wrap"><div class="crumbs"><button data-go="home">Home</button>${ic('chevr')}<span>Campaigns</span></div><div class="row between"><div><h1 style="font-size:clamp(28px,3.4vw,40px)">Campaign marketplace</h1><p class="muted" style="margin-top:6px;max-width:620px">Businesses post a brief and a budget. Verified creators send proposals. BitPromo protects the payment either way.</p></div><button class="btn btn-pri" data-act="postCamp">${ic('plus')}Post a campaign</button></div></div></div>
 <div class="wrap sec" style="padding-top:28px"><div class="grid g2" style="margin-bottom:32px">${[['Buy Now','Business picks a creator package and orders straight away. Fixed price, fixed delivery.','package','explore','Browse creators'],['Campaign','Business publishes a campaign. Creators apply with a price and an idea. Business hires the best fit.','megaphone',null,'Post a campaign']].map(([h,p,i,g,l])=>`<div class="card pad row" style="flex-wrap:nowrap;align-items:flex-start;gap:16px"><span class="fi" style="width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent);flex:none">${ic(i)}</span><div class="stack" style="gap:6px"><span class="eyebrow">Model</span><h3>${h}</h3><p class="muted small">${p}</p><button class="btn-link" ${g?`data-go="${g}"`:'data-act="postCamp"'}>${l} ${ic('arrow')}</button></div></div>`).join('')}</div>
 <div class="chips" style="margin-bottom:22px">${cats.map(c=>`<button class="chipt ${S.campCat===c?'on':''}" data-act="campCat" data-v="${c}">${c}</button>`).join('')}</div>
 <div class="grid g3">${list.map(campCard).join('')}</div></div>`;};
ACT.campCat=el=>{S.campCat=el.dataset.v;render();};
ACT.apply=el=>{const k=CAMPAIGNS.find(x=>x.id===el.dataset.id);modal(`${mhead('Apply for campaign')}<form class="modal-body" data-form="apply" data-id="${k.id}"><div class="row">${bizAv(B(k.b),40)}<div><b>${esc(k.title)}</b><div class="small muted">${esc(B(k.b).name)} · budget ${tk(k.budget)}</div></div></div><div><label class="small" style="font-weight:650" for="ap-p">Your price (৳)</label><input class="field" id="ap-p" type="number" value="${k.budget-1000}"></div><div><label class="small" style="font-weight:650" for="ap-m">Your idea</label><textarea class="field" id="ap-m">I’d film this as a short story with a real reaction moment, delivered in ${k.days-1} days. Script included.</textarea></div><p class="small muted">Applying as Ayesha Rahman (demo creator). You’ll receive 80% of the agreed price.</p><button class="btn btn-pri" type="submit">Send proposal</button></form>`);};
FORM.apply=f=>{S.applied.add(f.dataset.id);closeModal();toast('Proposal sent to the business');render();};
ACT.postCamp=()=>modal(`${mhead('Post a campaign')}<form class="modal-body" data-form="postCamp"><div><label class="small" style="font-weight:650" for="pc-t">Campaign title</label><input class="field" id="pc-t" name="t" value="Weekend brunch launch video" required></div><div class="form"><div><label for="pc-b">Budget (৳)</label><input class="field" id="pc-b" name="b" type="number" value="20000"></div><div><label for="pc-d">Deadline (days)</label><input class="field" id="pc-d" name="d" type="number" value="10"></div><div><label for="pc-c">Creator type</label><select class="field" id="pc-c" name="c">${CATS.map(c=>`<option>${c.n}</option>`).join('')}</select></div><div><label for="pc-p">Platform</label><select class="field" id="pc-p" name="p"><option>Facebook</option><option>Instagram</option><option>TikTok</option><option>YouTube</option></select></div></div><div><label class="small" style="font-weight:650" for="pc-x">What do you need?</label><input class="field" id="pc-x" name="x" value="30-second video featuring our new brunch menu"></div><button class="btn btn-pri" type="submit">Publish campaign</button></form>`);
FORM.postCamp=f=>{const id='k'+(CAMPAIGNS.length+1);CAMPAIGNS.unshift({id,b:ME_BIZ,title:f.t.value,budget:+f.b.value||10000,city:'Dhaka',content:f.x.value,days:+f.d.value||7,apps:0,cat:f.c.value,plat:f.p.value});S.myCamps.unshift(id);if(!S.role)S.role='biz';closeModal();toast('Campaign published. Creators can apply now.');render();};

