PAGES.business=()=>`<section class="hero"><div class="wrap hero-in"><div><span class="eyebrow" style="color:var(--accent)">For businesses</span><h1 style="margin-top:14px">Your brand deserves a face <span>people trust.</span></h1><p class="hero-sub">Work with verified Bangladeshi creators, actors and influencers. Brief them clearly, pay safely, and approve every video before it goes live.</p><div class="hero-ctas"><button class="btn btn-light btn-lg" data-go="explore">Find a Creator</button><button class="btn btn-outline-light btn-lg" data-act="postCamp">Launch a campaign</button></div></div>
 <div class="grid g2" style="gap:14px">${['c7','c4','c13','c2'].map((id,i)=>vt(C(id),{r:'v',i,title:['Food','Brand film','Beauty','Tech'][i]})).join('')}</div></div></section>
 <section class="sec"><div class="wrap"><div class="sec-head"><h2>Everything a business needs to get a promo video made</h2></div><div class="grid g3">${[['compass','Find creators','Search 20+ categories by city, language, audience and budget.'],['megaphone','Launch campaigns','Post a brief and budget, and let creators pitch you.'],['video','Create promotional videos','Fixed packages from 15-second reels to 60-second brand films.'],['users','Reach new audiences','Tap into creators’ followers on Facebook, Instagram, TikTok and YouTube.'],['badge','Work with verified creators','Identity, social profile and portfolio checked before they can sell.'],['lock','Protected payment','Your money stays with BitPromo until you approve the video.']].map(([i,h,p])=>`<div class="card pad feat"><span class="fi">${ic(i)}</span><div><h4>${h}</h4><p class="muted small">${p}</p></div></div>`).join('')}</div></div></section>
 <section class="sec sec-alt"><div class="wrap"><div class="sec-head"><h2>How your money is protected</h2></div>${escrowFlow()}</div></section>
 <section class="sec"><div class="wrap"><div class="sec-head"><h2>Creators businesses book most</h2><button class="btn btn-ghost btn-sm" data-go="explore">See all</button></div><div class="grid g4">${['c1','c7','c5','c12'].map((id,i)=>creatorCard(C(id),i)).join('')}</div></div></section>
 <section class="sec" style="padding-top:0"><div class="wrap"><div class="final"><h2>Find the creator. Create the content. Grow your brand.</h2><div class="row" style="justify-content:center;margin-top:24px"><button class="btn btn-light btn-lg" data-go="explore">Find a Creator</button><button class="btn btn-outline-light btn-lg" data-go="join">Create business account</button></div></div></div></section>`;
PAGES.creators=()=>`<section class="hero"><div class="wrap hero-in"><div><span class="eyebrow" style="color:var(--accent)">For creators</span><h1 style="margin-top:14px">Turn your influence <span>into income.</span></h1><p class="hero-sub">Create promotional content for brands, get paid for your work, and grow your professional opportunities through BitPromo.</p><div class="hero-ctas"><button class="btn btn-light btn-lg" data-go="join~creator">Become a Creator</button><button class="btn btn-outline-light btn-lg" data-go="dash~creator~home">Preview the creator dashboard</button></div></div>
 <div class="card pad stack" style="background:var(--night-2);border-color:var(--night-line);color:var(--on-night);gap:16px"><h3>Earnings calculator</h3><div><div class="row between small"><label for="calc-p">Your package price</label><b class="tnum" id="calc-pv">৳10,000</b></div><input type="range" id="calc-p" min="2000" max="50000" step="1000" value="10000" data-calc></div><div><div class="row between small"><label for="calc-n">Orders per month</label><b class="tnum" id="calc-nv">8</b></div><input type="range" id="calc-n" min="1" max="30" value="8" data-calc></div>
 <div style="border-top:1px solid var(--night-line);padding-top:14px"><div class="small" style="color:var(--on-night-2)">You could earn per month</div><div class="pkg-price" style="color:var(--ink);font-size:40px" id="calc-out">৳64,000</div><div class="small" style="color:var(--on-night-2)" id="calc-sub">After BitPromo’s 20% commission (৳16,000)</div></div></div></div></section>
 <section class="sec"><div class="wrap"><div class="sec-head"><h2>Why creators join BitPromo</h2></div><div class="grid g4">${[['wallet','Earn from your audience','Turn followers into paid brand work.'],['briefcase','Work with brands','Restaurants, fashion labels, startups and more.'],['sliders','Set your own prices','Three packages, your rates, your delivery times.'],['package','Manage orders','Briefs, files, chat and deadlines in one place.'],['film','Build your portfolio','Every approved video can go on your profile.'],['lock','Secure transactions','Payment is secured before you start filming.'],['shield','Scope protection','Revision limits stop endless change requests.'],['trend','Grow your profile','Ratings and verified status bring repeat buyers.']].map(([i,h,p])=>`<div class="feat"><span class="fi">${ic(i)}</span><div><h4>${h}</h4><p class="muted small">${p}</p></div></div>`).join('')}</div></div></section>
 <section class="sec sec-alt"><div class="wrap"><div class="sec-head"><div><h2>Become a verified BitPromo creator</h2><p class="muted">Seven steps from sign-up to your verified badge.</p></div><button class="btn btn-pri" data-go="verify">Start verification</button></div>${vsteps(0)}</div></section>`;
POST.creators=()=>calc();
function calc(){const p=+($('#calc-p')||{}).value||10000,n=+($('#calc-n')||{}).value||8;if(!$('#calc-out'))return;$('#calc-pv').textContent=tk(p);$('#calc-nv').textContent=n;$('#calc-out').textContent=tk(p*n*.8);$('#calc-sub').textContent=`After BitPromo’s 20% commission (${tk(p*n*.2)})`;}
document.addEventListener('input',e=>{if(e.target.dataset&&'calc' in e.target.dataset)calc();});
PAGES.how=()=>`<div class="phead"><div class="wrap"><div class="crumbs"><button data-go="home">Home</button>${ic('chevr')}<span>How it works</span></div><h1 style="font-size:clamp(28px,3.4vw,40px)">From idea to promotional video. One platform.</h1><p class="muted" style="margin-top:8px;max-width:640px">BitPromo is a trusted promotional-content marketplace: discovery, content creation, secure payment and quality control in one flow.</p></div></div>
 <section class="sec"><div class="wrap">${steps4()}</div></section>
 <section class="sec sec-alt"><div class="wrap"><div class="sec-head"><div><h2>Two ways to buy</h2></div></div><div class="grid g2">${[['Buy Now','Pick a creator’s Basic, Standard or Premium package and order immediately.','explore','Browse creators'],['Campaign','Post your brief and budget. Creators apply and you choose the best proposal.','campaigns','See campaigns']].map(([h,p,g,l])=>`<div class="card pad stack"><h3>${h}</h3><p class="muted">${p}</p><button class="btn btn-ghost btn-sm" style="align-self:flex-start" data-go="${g}">${l}</button></div>`).join('')}</div></div></section>
 <section class="sec"><div class="wrap"><div class="sec-head"><div><h2>Every order follows the same eight stages</h2><p class="muted">Both sides see exactly where the order is, and BitPromo steps in at quality check.</p></div><button class="btn btn-ghost btn-sm" data-go="track~BP-24117">See a live order</button></div><div class="card pad"><div class="hstl">${STAGES.map((s,i)=>`<div class="${i<6?'done':''} ${i===6?'cur':''}">${s}</div>`).join('')}</div></div></div></section>
 <section class="sec sec-alt"><div class="wrap"><div class="sec-head"><h2>Your money is protected</h2></div>${escrowFlow()}<div class="card pad" style="margin-top:22px;max-width:560px"><h3 style="margin-bottom:12px">Revenue model: 20% marketplace commission</h3><div class="sumrow"><span>Creator service price</span><b>৳20,000</b></div><div class="sumrow" style="margin-top:6px"><span>BitPromo</span><b style="color:var(--accent)">৳4,000</b></div><div class="sumrow" style="margin:6px 0 14px"><span>Creator</span><b style="color:var(--good)">৳16,000</b></div>${splitBar(20000)}</div></div></section>`;
PAGES.trust=()=>`<div class="phead"><div class="wrap"><div class="crumbs"><button data-go="home">Home</button>${ic('chevr')}<span>Trust &amp; Safety</span></div><h1 style="font-size:clamp(28px,3.4vw,40px)">Trust &amp; Safety</h1><p class="muted" style="margin-top:8px;max-width:640px">How BitPromo keeps both sides safe, from the first message to the final payout.</p></div></div>
 <section class="sec"><div class="wrap"><div class="grid g2" style="gap:18px">${[['badge','Creator verification','Identity documents, social profile ownership and a portfolio review before a creator can sell.'],['building','Business verification','Trade licence or business page checks for buyers placing large orders.'],['lock','Secure marketplace transactions','Payments are held through BitPromo’s marketplace process and released after approval.'],['doc','Order documentation','Brief, files, messages and every status change are saved on the order.'],['eye','Content requirements','Videos are checked against the agreed brief: length, branding, offer text and format.'],['refresh','Revision rules','Each package states its revisions. Changes outside the brief need a new order.'],['scale','Dispute resolution','A structured review of the order record, with refund, release or split outcomes.'],['flag','Report system','Report a profile, message or video in two taps. Our team reviews every report.'],['alert','Fraud prevention','Off-platform payment requests are flagged, and suspicious accounts are paused.'],['users','Community guidelines','Respectful communication, honest reviews and lawful content for both sides.']].map(([i,h,p])=>`<div class="card pad feat"><span class="fi">${ic(i)}</span><div><h4>${h}</h4><p class="muted small">${p}</p></div></div>`).join('')}</div>
 <div class="demo-note" style="margin-top:24px">${ic('alert')}BitPromo is a marketplace, not a bank. Live payments would run through a licensed payment provider.</div></div></section>`;

/* ===== VERIFY ===== */
const VSTEPS=['Create profile','Identity','Social profiles','Portfolio','Submit','BitPromo review','Verified badge'];
function vsteps(cur){return `<div class="vsteps">${VSTEPS.map((s,i)=>`<div class="vstep ${i<cur?'done':''} ${i===cur?'cur':''}"><i>${i<cur?'✓':i+1}</i>${s}</div>`).join('')}</div>`;}
PAGES.verify=()=>{const v=S.ver,st=v.step;let body='';
 if(st===1)body=`<h2 style="font-size:22px">Create your creator profile</h2><div class="form" style="margin-top:16px"><div><label for="vf-1">Full name</label><input class="field" id="vf-1" value="Rumana Akhter"></div><div><label for="vf-2">City</label><select class="field" id="vf-2"><option>Dhaka</option><option>Chattogram</option><option>Sylhet</option></select></div><div><label for="vf-3">Main category</label><select class="field" id="vf-3">${CATS.map(c=>`<option>${c.n}</option>`).join('')}</select></div><div><label for="vf-4">Languages</label><input class="field" id="vf-4" value="Bangla, English"></div><div class="full"><label for="vf-5">Short bio</label><textarea class="field" id="vf-5">Home cook and food reviewer sharing Dhaka’s best street food and family recipes.</textarea></div></div>`;
 if(st===2)body=`<h2 style="font-size:22px">Upload identity information</h2><p class="muted" style="margin:6px 0 16px">Used only to confirm you are who you say you are. Not shown to buyers.</p><div class="grid g3" style="gap:12px">${[['nidf','NID front'],['nidb','NID back'],['selfie','Selfie holding NID']].map(([k,l])=>`<div class="drop" style="align-items:center;text-align:center"><span class="fi" style="width:44px;height:44px;border-radius:12px;background:var(--bg-2);display:grid;place-items:center;color:var(--muted)">${ic('id')}</span><b class="small">${l}</b>${v.files[k]?`<span class="filechip">${ic('check')}${esc(v.files[k])}</span>`:`<label class="btn btn-ghost btn-sm" for="vu-${k}" style="cursor:pointer">Upload</label><input type="file" id="vu-${k}" data-vup="${k}" accept="image/*" hidden>`}</div>`).join('')}</div><button class="btn-link" style="margin-top:12px" data-act="vSample">Use sample documents</button>`;
 if(st===3)body=`<h2 style="font-size:22px">Add your social profiles</h2><p class="muted" style="margin:6px 0 16px">We confirm you own these accounts and check follower numbers.</p><div class="form">${['Facebook','Instagram','YouTube','TikTok'].map(p=>`<div><label for="vs-${p}">${p}</label><input class="field" id="vs-${p}" value="${p.toLowerCase()}.com/rumana.eats"></div>`).join('')}</div>`;
 if(st===4)body=`<h2 style="font-size:22px">Add your portfolio</h2><p class="muted" style="margin:6px 0 16px">Upload 3–6 videos that show your on-camera style.</p><div class="grid g4 keep2">${Array.from({length:4},(_,i)=>vt({id:'c7',look:VERIFY_QUEUE[0].look},{r:'v',title:['Street food tour','Recipe reel','Café review','Brand shoutout'][i],i})).join('')}</div>`;
 if(st===5)body=`<h2 style="font-size:22px">Review and submit</h2><ul class="checks" style="margin:16px 0">${['Profile details complete','3 identity documents uploaded','4 social profiles linked','4 portfolio videos added'].map(x=>`<li>${ic('check')}${x}</li>`).join('')}</ul><label class="row" style="gap:10px;font-weight:500"><input type="checkbox" id="v-agree" checked> I agree to BitPromo’s creator terms and community guidelines.</label>`;
 if(st===6)body=`<div style="text-align:center;padding:20px 0" class="stack"><div class="spinner"></div><h2 style="font-size:22px">BitPromo is reviewing your application</h2><p class="muted">Reviews usually take 1–2 working days. We’ll message you when it’s done.</p><button class="btn btn-ghost btn-sm" style="align-self:center" data-act="vNext">Prototype: simulate approval</button></div>`;
 if(st===7)body=`<div style="text-align:center;padding:20px 0" class="stack"><div class="success-ic">${ic('badge')}</div><h2>You’re a Verified Creator ✓</h2><p class="muted">Your badge now shows on your profile and every listing.</p><div class="row" style="justify-content:center"><span class="verified-chip" style="font-size:15px;padding:6px 14px 6px 8px">${vb()}Verified Creator</span></div><button class="btn btn-pri" style="align-self:center" data-go="dash~creator~home">Go to creator dashboard</button></div>`;
 return `<div class="phead"><div class="wrap"><div class="crumbs"><button data-go="creators">For creators</button>${ic('chevr')}<span>Verification</span></div><h1 style="font-size:clamp(26px,3vw,36px)">Become a verified BitPromo creator</h1></div></div>
 <div class="wrap" style="padding-block:28px 64px;max-width:900px"><div class="card pad" style="margin-bottom:20px">${vsteps(st-1)}</div><div class="card pad" style="padding:clamp(18px,3vw,28px)">${body}</div>
 ${st<6?`<div class="row between" style="margin-top:18px">${st>1?`<button class="btn btn-ghost" data-act="vBack">${ic('chevl')}Back</button>`:'<span></span>'}<button class="btn btn-pri" data-act="vNext">${st===5?'Submit application':'Continue'}${ic('chevr')}</button></div>`:''}
 <p class="small muted" style="margin-top:18px">Verification is a platform status. It confirms these steps were completed. It does not guarantee a person’s identity or reputation beyond this process.</p></div>`;};
ACT.vNext=()=>{if(S.ver.step===5&&!$('#v-agree').checked){toast('Please accept the creator terms');return;}S.ver.step=Math.min(7,S.ver.step+1);if(S.ver.step===7)S.role='creator';render();window.scrollTo(0,0);};
ACT.vBack=()=>{S.ver.step=Math.max(1,S.ver.step-1);render();};
ACT.vSample=()=>{S.ver.files={nidf:'NID_front.jpg',nidb:'NID_back.jpg',selfie:'Selfie_with_NID.jpg'};render();};

/* ===== AUTH ===== */
PAGES.signin=()=>`<div class="auth"><div class="auth-art"><span class="eyebrow" style="color:var(--accent)">Welcome back</span><h2 style="font-size:40px">Your brand. Their influence. One powerful video.</h2><div class="grid g3" style="gap:10px;max-width:440px">${['c1','c5','c9'].map((id,i)=>vt(C(id),{r:'v',i})).join('')}</div></div>
 <div class="auth-form"><h1 style="font-size:32px">Sign in to BitPromo</h1><p class="muted">Pick a demo account to explore each side of the marketplace.</p>
 <div class="stack" style="gap:10px">${[['biz','Business demo','business@bitpromo.demo · Bhoj Kitchen','#FF7A59','building'],['creator','Creator demo','creator@bitpromo.demo · Ayesha Rahman','#2453FF','film'],['admin','Admin demo','admin@bitpromo.demo · BitPromo team','#0A1020','shield']].map(([r,t,s,c,i])=>`<button class="demo-acc" data-act="signinAs" data-r="${r}"><span class="fi" style="background:${c}">${ic(i)}</span><div class="grow"><b>${t}</b><div class="small muted">${s}</div></div>${ic('chevr')}</button>`).join('')}</div>
 <div class="row" style="gap:12px;color:var(--muted)"><span style="flex:1;height:1px;background:var(--line)"></span><span class="small">or sign in with email</span><span style="flex:1;height:1px;background:var(--line)"></span></div>
 <form class="stack" data-form="signin"><div><label class="small" style="font-weight:650" for="si-e">Email</label><input class="field" id="si-e" name="e" type="email" value="business@bitpromo.demo"></div><div><label class="small" style="font-weight:650" for="si-p">Password</label><input class="field" id="si-p" name="p" type="password" value="demo1234"></div><button class="btn btn-pri btn-block" type="submit">Sign in</button></form>
 <p class="small muted">New to BitPromo? <button class="btn-link" data-go="join">Create an account</button></p></div></div>`;
FORM.signin=f=>{const e=f.e.value.trim().toLowerCase();const r=Object.keys(USERS).find(k=>USERS[k].email===e);if(!r){toast('Use one of the three demo emails above');return;}ACT.signinAs({dataset:{r}});};
ACT.signinAs=el=>{const r=el.dataset.r;S.role=r;S.thread=null;go(`dash~${r}~${r==='admin'?'overview':'home'}`);};
ACT.signout=()=>{S.role=null;toast('Signed out');go('home');};
PAGES.join=(role)=>{S.joinRole=role==='creator'?'creator':S.joinRole||'biz';const r=S.joinRole;return `<div class="auth"><div class="auth-art"><span class="eyebrow" style="color:var(--accent)">Get started</span><h2 style="font-size:40px">${r==='creator'?'Turn your influence into income.':'Find the right face for your brand.'}</h2><ul class="checks" style="color:var(--on-night)">${(r==='creator'?['Set your own prices','Get paid after approval','Verified badge on your profile']:['Verified creators across Bangladesh','Payment held until you approve','Quality check on every video']).map(x=>`<li>${ic('check')}${x}</li>`).join('')}</ul></div>
 <div class="auth-form"><h1 style="font-size:32px">Create your account</h1><div class="role-pick">${[['biz','I’m a business','Hire creators for promotional videos','building'],['creator','I’m a creator','Sell promotional video content','film']].map(([k,t,s,i])=>`<button class="${r===k?'on':''}" data-act="joinRole" data-r="${k}"><span style="color:var(--accent)">${ic(i)}</span><b>${t}</b><span class="small muted">${s}</span></button>`).join('')}</div>
 <form class="stack" data-form="join">${r==='biz'?`<div><label class="small" style="font-weight:650" for="j-b">Business name</label><input class="field" id="j-b" value="Bhoj Kitchen"></div><div><label class="small" style="font-weight:650" for="j-t">Business type</label><select class="field" id="j-t"><option>Restaurant</option><option>Fashion brand</option><option>E-commerce</option><option>Startup</option><option>Real estate</option><option>Education</option><option>Other</option></select></div>`:`<div><label class="small" style="font-weight:650" for="j-n">Full name</label><input class="field" id="j-n" value="Rumana Akhter"></div>`}
 <div><label class="small" style="font-weight:650" for="j-e">Email</label><input class="field" id="j-e" type="email" value="${r==='biz'?'business':'creator'}@bitpromo.demo"></div><div><label class="small" style="font-weight:650" for="j-p">Password</label><input class="field" id="j-p" type="password" value="demo1234"></div>
 <button class="btn btn-pri btn-block" type="submit">${r==='biz'?'Create business account':'Continue to verification'}</button></form><p class="small muted">Already have an account? <button class="btn-link" data-go="signin">Sign in</button></p></div></div>`;};
ACT.joinRole=el=>{S.joinRole=el.dataset.r;render();};
FORM.join=()=>{if(S.joinRole==='creator'){S.ver.step=1;go('verify');toast('Account created. Let’s get you verified.');}else{S.role='biz';go('dash~biz~home');toast('Business account created');}};
PAGES.messages=()=>{const r=S.role||'biz';ROUTE=`dash~${r}~messages`;return PAGES.dash(r,'messages');};

/* ===== menu / drawer ===== */
ACT.menu=()=>{const u=S.role;const L=(g,l,i)=>`<button class="dl" data-go="${g}">${ic(i)}${l}</button>`;
 $('#modal-root').innerHTML=`<div class="drawer" data-act="bg"><div class="drawer-in"><div class="row between" style="margin-bottom:10px"><button class="logo" data-go="home"><span class="logo-mark">${ic('play','i-fill')}</span><span>Bit<b>Promo</b></span></button><button class="iconbtn" data-act="close" aria-label="Close menu">${ic('x')}</button></div>
 ${u?`<div class="row" style="padding:10px;border:1px solid var(--line);border-radius:12px;margin-bottom:8px">${userAv(40)}<div><b>${USERS[u].name}</b><div class="small muted">${USERS[u].email}</div></div></div>${L(`dash~${u}~${u==='admin'?'overview':'home'}`,'Dashboard','grid')}`:''}
 ${L('home','Home','home')}${L('explore','Explore Creators','compass')}${L('categories','Categories','grid')}${L('how','How It Works','refresh')}${L('business','For Businesses','building')}${L('creators','For Creators','film')}${L('campaigns','Campaigns','megaphone')}${L('trust','Trust & Safety','shield')}
 <div style="margin-top:auto;display:flex;flex-direction:column;gap:8px;padding-top:16px">${u?`<button class="btn btn-ghost btn-block" data-act="signout">${ic('logout')}Sign out</button>`:`<button class="btn btn-ghost btn-block" data-go="signin">Sign In</button><button class="btn btn-pri btn-block" data-go="join">Get Started</button><button class="btn btn-ghost btn-block" data-go="creators">Become a Creator</button>`}</div></div></div>`;};
